//! Secure share: a `.lokishare` file holding one or more `.env` files, readable only with a
//! one-time pass key.
//!
//! - The pass key is generated by LOKI (never typed by a person): 25 Crockford base32 characters,
//!   125 bits of entropy, shown as `XXXXX-XXXXX-XXXXX-XXXXX-XXXXX`. LOKI never stores it.
//! - The file is Argon2id + XChaCha20-Poly1305, the same format as `.loki` backups, with the
//!   header authenticated as associated data. Without the pass key nothing inside is readable,
//!   not even the project names.
//! - Format 2 holds a list of items (one per `.env`), each with its project, branch and stage so
//!   the recipient can import it into the matching target in one step. Format 1 files (a single
//!   `.env`) still open.
//! - An optional expiry date travels inside the encrypted payload. LOKI refuses to import an
//!   expired share. (Expiry is enforced by LOKI, not by the cryptography: anyone holding both the
//!   file and the pass key could still decrypt it with their own tools.)

use crate::core::backup;
use crate::core::crypto::{random_bytes, random_index, to_hex, KdfParams};
use crate::core::parser::{is_valid_key, Entry};
use crate::error::{LokiError, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use zeroize::{Zeroize, Zeroizing};

const MAGIC: &[u8; 8] = b"LOKISHR1";
const ALPHABET: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";
pub const PASS_KEY_CHARS: usize = 25;
pub const MAX_ITEMS: usize = 100;
const FORMAT: u32 = 2;

#[derive(Serialize, Deserialize)]
pub struct ShareVar {
    pub key: String,
    pub value: String,
    pub comment: Option<String>,
}

impl Drop for ShareVar {
    fn drop(&mut self) {
        self.value.zeroize();
        if let Some(c) = self.comment.as_mut() {
            c.zeroize();
        }
    }
}

/// One `.env` inside a share.
#[derive(Serialize, Deserialize)]
pub struct ShareItem {
    /// e.g. "Payments API / main / production v3". Names only, never values.
    pub label: String,
    #[serde(default)]
    pub project: Option<String>,
    #[serde(default)]
    pub branch: Option<String>,
    #[serde(default)]
    pub stage: Option<String>,
    pub entries: Vec<ShareVar>,
}

#[derive(Serialize, Deserialize)]
pub struct SharePayload {
    pub format: u32,
    pub created_at: String,
    pub expires_at: Option<String>,
    pub note: Option<String>,
    #[serde(default)]
    pub items: Vec<ShareItem>,
    // Format 1 kept a single .env at the top level. Read for compatibility, never written.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub source: String,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub entries: Vec<ShareVar>,
}

impl SharePayload {
    pub fn new(created_at: String, expires_at: Option<String>, note: Option<String>, items: Vec<ShareItem>) -> Self {
        SharePayload { format: FORMAT, created_at, expires_at, note, items, source: String::new(), entries: vec![] }
    }

    pub fn key_count(&self) -> usize {
        self.items.iter().map(|i| i.entries.len()).sum()
    }
}

/// A decrypted share held in memory (inside the vault state, dropped on lock).
pub struct PendingShare {
    pub token: String,
    pub payload: SharePayload,
}

#[derive(Serialize, Debug)]
#[serde(rename_all = "camelCase")]
pub struct SharePreviewKey {
    pub key: String,
    pub is_empty: bool,
    pub has_comment: bool,
}

#[derive(Serialize, Debug)]
#[serde(rename_all = "camelCase")]
pub struct SharePreviewItem {
    pub index: usize,
    pub label: String,
    pub project: Option<String>,
    pub branch: Option<String>,
    pub stage: Option<String>,
    pub keys: Vec<SharePreviewKey>,
}

/// What the recipient sees before importing: names, counts and dates. No values.
#[derive(Serialize, Debug)]
#[serde(rename_all = "camelCase")]
pub struct SharePreview {
    pub token: String,
    pub items: Vec<SharePreviewItem>,
    pub created_at: String,
    pub expires_at: Option<String>,
    pub expired: bool,
    pub note: Option<String>,
}

pub fn generate_pass_key() -> Result<Zeroizing<String>> {
    let mut out = Zeroizing::new(String::with_capacity(PASS_KEY_CHARS + 4));
    for i in 0..PASS_KEY_CHARS {
        if i > 0 && i % 5 == 0 {
            out.push('-');
        }
        out.push(ALPHABET[random_index(32)? as usize] as char);
    }
    Ok(out)
}

/// Accepts what a person types: any case, with or without dashes or spaces, and the usual
/// look-alikes (O for 0, I or L for 1).
pub fn normalize_pass_key(input: &str) -> Zeroizing<String> {
    Zeroizing::new(
        input
            .chars()
            .filter(|c| !c.is_whitespace() && *c != '-')
            .map(|c| match c.to_ascii_uppercase() {
                'O' => '0',
                'I' | 'L' => '1',
                other => other,
            })
            .collect(),
    )
}

/// True for a key in LOKI's generated format (after normalization).
pub fn is_pass_key(input: &str) -> bool {
    let k = normalize_pass_key(input);
    k.len() == PASS_KEY_CHARS && k.bytes().all(|b| ALPHABET.contains(&b))
}

pub fn seal(payload: &SharePayload, pass_key: &str, kdf: KdfParams) -> Result<Vec<u8>> {
    if !is_pass_key(pass_key) {
        return Err(LokiError::Invalid("Use the pass key LOKI generated for this share.".into()));
    }
    if payload.items.is_empty() || payload.items.iter().any(|i| i.entries.is_empty()) {
        return Err(LokiError::Invalid("Choose at least one key in every .env you share.".into()));
    }
    let key = normalize_pass_key(pass_key);
    let json = Zeroizing::new(serde_json::to_vec(payload).map_err(|_| LokiError::Crypto)?);
    backup::encrypt_with(MAGIC, &json, &key, kdf)
}

pub fn open(file: &[u8], pass_key: &str) -> Result<PendingShare> {
    if !is_pass_key(pass_key) {
        return Err(LokiError::Invalid(format!("A pass key has {PASS_KEY_CHARS} letters and digits, like ABCDE-12345-…")));
    }
    let key = normalize_pass_key(pass_key);
    let json = backup::decrypt_with(MAGIC, file, &key, LokiError::WrongPassKey, "That is not a LOKI share file (.lokishare).")?;
    let mut payload: SharePayload = serde_json::from_slice(&json).map_err(|_| LokiError::Invalid("This share file is damaged.".into()))?;
    match payload.format {
        1 => {
            // Old single-.env share: lift it into one item.
            let entries = std::mem::take(&mut payload.entries);
            let label = std::mem::take(&mut payload.source);
            payload.items = vec![ShareItem { label, project: None, branch: None, stage: None, entries }];
            payload.format = FORMAT;
        }
        FORMAT => {}
        _ => return Err(LokiError::Invalid("This share was made by a newer version of LOKI. Update LOKI to open it.".into())),
    }
    if payload.items.is_empty() || payload.items.len() > MAX_ITEMS {
        return Err(LokiError::Invalid("This share file is damaged.".into()));
    }
    for item in &payload.items {
        let mut seen = HashSet::new();
        for v in &item.entries {
            if !is_valid_key(&v.key) || !seen.insert(v.key.clone()) {
                return Err(LokiError::Invalid("This share contains an invalid or duplicate key name.".into()));
            }
        }
        if let Some(stage) = &item.stage {
            crate::db::repo::validate_stage(stage)?;
        }
    }
    Ok(PendingShare { token: to_hex(&random_bytes::<16>()?), payload })
}

pub fn is_expired(p: &SharePayload, now: &str) -> bool {
    p.expires_at.as_deref().is_some_and(|e| e <= now)
}

pub fn preview(share: &PendingShare, now: &str) -> SharePreview {
    let p = &share.payload;
    SharePreview {
        token: share.token.clone(),
        items: p
            .items
            .iter()
            .enumerate()
            .map(|(index, i)| SharePreviewItem {
                index,
                label: i.label.clone(),
                project: i.project.clone(),
                branch: i.branch.clone(),
                stage: i.stage.clone(),
                keys: i.entries.iter().map(|e| SharePreviewKey { key: e.key.clone(), is_empty: e.value.is_empty(), has_comment: e.comment.is_some() }).collect(),
            })
            .collect(),
        created_at: p.created_at.clone(),
        expires_at: p.expires_at.clone(),
        expired: is_expired(p, now),
        note: p.note.clone(),
    }
}

pub fn entries(item: &ShareItem) -> Vec<Entry> {
    item.entries.iter().map(|v| Entry { key: v.key.clone(), value: v.value.clone(), comment: v.comment.clone(), line: 0 }).collect()
}

pub fn from_entries(entries: &[Entry], only: Option<&HashSet<String>>) -> Vec<ShareVar> {
    entries
        .iter()
        .filter(|e| only.is_none_or(|k| k.contains(&e.key)))
        .map(|e| ShareVar { key: e.key.clone(), value: e.value.clone(), comment: e.comment.clone() })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::crypto::TEST_PARAMS;
    use crate::core::parser::parse;

    fn item(project: &str, stage: &str, text: &str) -> ShareItem {
        ShareItem {
            label: format!("{project} / main / {stage} v1"),
            project: Some(project.into()),
            branch: Some("main".into()),
            stage: Some(stage.into()),
            entries: from_entries(&parse(text).entries, None),
        }
    }

    fn payload(expires: Option<&str>) -> SharePayload {
        SharePayload::new(
            "2026-11-11T10:00:00Z".into(),
            expires.map(Into::into),
            Some("for the new laptop".into()),
            vec![item("API", "production", "# db\nA=fake_value_1\nB=\n"), item("Web", "staging", "C=fake_value_3\n")],
        )
    }

    #[test]
    fn pass_keys_look_right_and_are_random() {
        let a = generate_pass_key().unwrap();
        let b = generate_pass_key().unwrap();
        assert_eq!(a.len(), 29);
        assert_eq!(a.matches('-').count(), 4);
        assert_ne!(*a, *b);
        assert!(is_pass_key(&a));
    }

    #[test]
    fn normalization_forgives_typing() {
        assert_eq!(*normalize_pass_key(" abcde-fghjk o0il1 "), "ABCDEFGHJK00111");
        assert!(!is_pass_key("my own easy password"));
        assert!(!is_pass_key("ABCDE-FGHJK"));
    }

    #[test]
    fn a_bundle_of_several_env_files_round_trips() {
        let key = generate_pass_key().unwrap();
        let file = seal(&payload(None), &key, TEST_PARAMS).unwrap();
        assert!(file.starts_with(b"LOKISHR1"));
        for needle in [&b"fake_value_1"[..], b"production", b"API", b"laptop"] {
            assert!(!file.windows(needle.len()).any(|w| w == needle), "plaintext leaked");
        }
        let typed = key.to_lowercase().replace('-', " ");
        let opened = open(&file, &typed).unwrap();
        assert_eq!(opened.payload.items.len(), 2);
        assert_eq!(opened.payload.key_count(), 3);
        let first = entries(&opened.payload.items[0]);
        assert_eq!((first[0].key.as_str(), first[0].value.as_str(), first[0].comment.as_deref()), ("A", "fake_value_1", Some("db")));
        assert_eq!(opened.payload.items[1].stage.as_deref(), Some("staging"));
    }

    #[test]
    fn version_1_single_env_files_still_open() {
        let key = generate_pass_key().unwrap();
        let v1 = br#"{"format":1,"created_at":"2026-11-11T10:00:00Z","expires_at":null,"source":"API / main / production v3","note":null,"entries":[{"key":"A","value":"fake_value_1","comment":null}]}"#;
        let file = backup::encrypt_with(MAGIC, v1, &normalize_pass_key(&key), TEST_PARAMS).unwrap();
        let opened = open(&file, &key).unwrap();
        assert_eq!(opened.payload.items.len(), 1);
        assert_eq!(opened.payload.items[0].label, "API / main / production v3");
        assert_eq!(opened.payload.items[0].project, None, "old files carry no structured names");
        assert_eq!(entries(&opened.payload.items[0])[0].value, "fake_value_1");
    }

    #[test]
    fn only_generated_pass_keys_can_seal() {
        assert!(seal(&payload(None), "password123", TEST_PARAMS).is_err());
        let mut empty = payload(None);
        empty.items[1].entries.clear();
        assert!(seal(&empty, &generate_pass_key().unwrap(), TEST_PARAMS).is_err(), "an .env with no keys is refused");
    }

    #[test]
    fn wrong_key_tampering_and_wrong_file_type_fail() {
        let key = generate_pass_key().unwrap();
        let file = seal(&payload(None), &key, TEST_PARAMS).unwrap();
        assert!(matches!(open(&file, &generate_pass_key().unwrap()), Err(LokiError::WrongPassKey)));
        assert!(matches!(open(&file, "too-short"), Err(LokiError::Invalid(_))));
        let mut t = file.clone();
        let n = t.len() - 3;
        t[n] ^= 1;
        assert!(open(&t, &key).is_err());
        let backup_file = backup::encrypt(b"{}", &normalize_pass_key(&key), TEST_PARAMS).unwrap();
        assert!(matches!(open(&backup_file, &key), Err(LokiError::Invalid(_))));
    }

    #[test]
    fn preview_has_no_values_and_reports_expiry() {
        let key = generate_pass_key().unwrap();
        let file = seal(&payload(Some("2026-11-12T10:00:00Z")), &key, TEST_PARAMS).unwrap();
        let share = open(&file, &key).unwrap();
        let before = preview(&share, "2026-11-12T09:59:59Z");
        assert!(!before.expired);
        assert!(preview(&share, "2026-11-12T10:00:00Z").expired);
        let json = serde_json::to_string(&before).unwrap();
        assert!(!json.contains("fake_value"));
        assert_eq!(before.items.len(), 2);
        assert_eq!(before.items[0].keys.len(), 2);
        assert!(before.items[0].keys[0].has_comment && before.items[0].keys[1].is_empty);
        assert_eq!((before.items[1].index, before.items[1].project.as_deref()), (1, Some("Web")));
    }

    #[test]
    fn subset_of_keys() {
        let only: HashSet<String> = ["B".to_string()].into();
        let v = from_entries(&parse("A=fake_value_1\nB=fake_value_2\n").entries, Some(&only));
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].key, "B");
    }

    /// Writes a sample two-.env share for end-to-end testing:
    /// `LOKI_SHARE_FIXTURE_DIR=<dir> cargo test write_share_fixture -- --ignored`
    #[test]
    #[ignore]
    fn write_share_fixture() {
        let Some(dir) = std::env::var_os("LOKI_SHARE_FIXTURE_DIR") else { return };
        let dir = std::path::PathBuf::from(dir);
        let key = generate_pass_key().unwrap();
        let p = SharePayload::new(
            "2026-11-12T10:00:00Z".into(),
            Some("2099-01-01T00:00:00Z".into()),
            Some("Keys for your first day".into()),
            vec![
                item("Shared Demo", "production", "SHARED_API_KEY=fake_shared_value_1\nSHARED_URL=fake_shared_value_2\n"),
                item("Shared Demo", "staging", "SHARED_API_KEY=fake_shared_value_3\n"),
            ],
        );
        std::fs::write(dir.join("fixture.lokishare"), seal(&p, &key, TEST_PARAMS).unwrap()).unwrap();
        std::fs::write(dir.join("fixture.passkey"), key.as_bytes()).unwrap();
    }
}
